{"path": "units/csvfix/impl.py", "content": """"固定 3 列的 CSV 行解析与小计。

约定（见测试）：
- 一行恰好 3 列，列内容两端空白被裁剪；带引号的字段按标准 CSV 规则处理
  （引号内的逗号不分割字段）。
- 列数不是 3、或引号不闭合等无法解析时返回 None。
- total 以**第 3 列**为金额：跳过空白字段，遇到非数字字段抛 ValueError。
"""

import csv


def parse(line):
    """解析一行 CSV，返回 3 个已裁剪的字符串组成的列表；不合法返回 None。"""
    try:
        rows = list(csv.reader([line]))
    except (csv.Error, StopIteration):
        return None
    if len(rows) != 1:
        return None
    fields = [f.strip() for f in rows[0]]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """累加行的第 3 列（金额）。空白字段跳过（贡献 0），非数字抛 ValueError。"""
    result = 0
    for r in rows:
        if len(r) < 3:
            raise ValueError("row has fewer than 3 columns: %r" % (r,))
        field = r[2].strip()
        if field == "":
            continue
        result += int(field)
    return result
"}

{"path": "units/rules/engine.py", "content": """"极小的规则求值器。

规则是单键字典，支持两种形式：
- {"all": [fact_key, ...]}：所有 fact 都为真才为 True（空列表为 True）。
- {"any": [fact_key, ...]}：任一 fact 为真即为 True（空列表为 False）。

未在 facts 中出现的键视为假。其他键（未知操作）抛 ValueError。
"""


def evaluate(rules, facts):
    if not isinstance(rules, dict) or len(rules) != 1:
        raise ValueError("rule must be a single-key dict: %r" % (rules,))
    (op, keys), = rules.items()
    if op == "all":
        return all(bool(facts.get(k, False)) for k in keys)
    if op == "any":
        return any(bool(facts.get(k, False)) for k in keys)
    raise ValueError("unknown rule operator: %r" % (op,))
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""

VALID_KINDS = ("deposit", "withdraw")


class Ledger:
    def apply(self, rows, op):
        """rows 是 [(kind, account, cents), ...]，返回**该账户**的行（保持原顺序）。

        - kind 只能是 "deposit" 或 "withdraw"，否则抛 ValueError。
        - 金额为负时抛 ValueError。
        - 校验针对输入中的每一行（包括其他账户的行），不修改输入。
        """
        for row in rows:
            kind, _account, cents = row
            if kind not in VALID_KINDS:
                raise ValueError("unknown kind: %r" % (kind,))
            if cents < 0:
                raise ValueError("negative amount: %r" % (cents,))
        return [row for row in rows if row[1] == op]


def balance(rows, account):
    """返回该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    total = 0
    for kind, acc, cents in rows:
        if acc != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
        else:
            raise ValueError("unknown kind: %r" % (kind,))
    return total
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。
    返回按起点升序的合并结果；空输入返回 []。
    """
    if not ranges:
        return []
    ordered = sorted((lo, hi) for lo, hi in ranges)
    merged = [ordered[0]]
    for lo, hi in ordered[1:]:
        prev_lo, prev_hi = merged[-1]
        if lo - prev_hi < minutes:
            # 重叠（lo <= prev_hi）或空隙小于阈值：合并，端点取更远者。
            merged[-1] = (prev_lo, max(prev_hi, hi))
        else:
            merged.append((lo, hi))
    return merged


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    a_lo, a_hi = a
    b_lo, b_hi = b
    return a_lo < b_hi and b_lo < a_hi
"}

{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回 [(lo, hi), ...] 升序；空输入返回 []。
        """
        if not ranges:
            return []
        ordered = sorted((lo, hi) for lo, hi in ranges)
        merged = [ordered[0]]
        for lo, hi in ordered[1:]:
            prev_lo, prev_hi = merged[-1]
            missing = lo - prev_hi - 1
            if missing <= gap:
                merged[-1] = (prev_lo, max(prev_hi, hi))
            else:
                merged.append((lo, hi))
        return merged

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。
        与 hole 不相交的段原样保留，被完全覆盖的段消失，横跨 hole 的段分裂成两段。
        输入先按 merge(gap=0) 规范化。
        """
        hole_lo, hole_hi = hole
        result = []
        for lo, hi in self.merge(ranges):
            if hi < hole_lo or lo > hole_hi:
                result.append((lo, hi))
                continue
            if lo <= hole_lo - 1:
                result.append((lo, hole_lo - 1))
            if hi >= hole_hi + 1:
                result.append((hole_hi + 1, hi))
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}
